def solve(kinds):
    class Email:
        def send(self):
            return "email:ok"

    class Sms:
        def send(self):
            return "sms:ok"

    table = {"email": Email(), "sms": Sms()}
    results = [table[kind].send() for kind in kinds]
    return {"results": results, "deleted_checks": ["email", "sms"]}
